-- -----------------------------------------------------
-- Schema ecommerce
-- -----------------------------------------------------
DROP SCHEMA IF EXISTS `ecommerce`;

CREATE SCHEMA `ecommerce`;
USE `ecommerce` ;

-- -----------------------------------------------------
-- Table `ecommerce`.`categories`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `ecommerce`.`categories` (
  `id` BIGINT(20) NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(255) NULL DEFAULT NULL,
  PRIMARY KEY (`id`))
ENGINE=InnoDB
AUTO_INCREMENT = 1;

-- -----------------------------------------------------
-- Table `ecommerce`.`products`
-- -----------------------------------------------------
CREATE TABLE IF NOT EXISTS `ecommerce`.`products` (
  `id` BIGINT(20) NOT NULL AUTO_INCREMENT,
  `sku` VARCHAR(255) DEFAULT NULL,
  `name` VARCHAR(255) DEFAULT NULL,
  `description` VARCHAR(255) DEFAULT NULL,
  `unit_price` DECIMAL(13,2) DEFAULT NULL,
  `image_url` VARCHAR(255) DEFAULT NULL,
  `active` BIT DEFAULT 1,
  `units_in_stock` INT(11) DEFAULT NULL,
  `created_at` DATETIME(6) DEFAULT NULL,
  `updated_at` DATETIME(6) DEFAULT NULL,
  `category_id` BIGINT(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_category` (`category_id`),
  CONSTRAINT `fk_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)
) 
ENGINE=InnoDB
AUTO_INCREMENT = 1;

-- -----------------------------------------------------
-- Categories
-- -----------------------------------------------------

-- -----------------------------------------------------
-- Books
-- -----------------------------------------------------

UPDATE products
SET description = CASE sku
  WHEN 'BOOK-TECH-1000' THEN 'Start writing useful Python with variables, control flow, functions, and small projects. Clear explanations and practical exercises help beginners move from a first script to useful programs.'
  WHEN 'BOOK-TECH-1001' THEN 'Explore modern JavaScript, from scope and asynchronous code to modules and browser APIs. Practical examples show how to build responsive, maintainable applications.'
  WHEN 'BOOK-TECH-1002' THEN 'Build interactive interfaces with Vue components, templates, reactive state, and routing. A guided progression takes you from a small page to a structured application.'
  WHEN 'BOOK-TECH-1003' THEN 'Explore distributed storage, batch processing, and stream pipelines. Learn how large-scale data systems handle growth, reliability, and the challenges of moving information.'
  WHEN 'BOOK-TECH-1004' THEN 'Get a friendly introduction to datasets, data pipelines, and distributed computing. Follow a practical workflow for collecting, organizing, and analyzing information at scale.'
  WHEN 'BOOK-TECH-1005' THEN 'A hands-on collection of JavaScript recipes for forms, arrays, browser events, network requests, and everyday interface challenges. Each example solves one focused problem.'
  WHEN 'BOOK-TECH-1006' THEN 'Learn to retrieve and shape information with SELECT, filtering, sorting, joins, and basic aggregation. Short query examples help new analysts work confidently with relational data.'
  WHEN 'BOOK-TECH-1007' THEN 'Strengthen JavaScript skills with closures, promises, iterators, prototypes, and performance patterns. Examples connect language mechanics to real application design.'
  WHEN 'BOOK-TECH-1008' THEN 'Create a Spring Boot service from the first endpoint through configuration, dependency injection, persistence, and testing, with a foundation for production-minded Java apps.'
  WHEN 'BOOK-TECH-1009' THEN 'Learn React by composing reusable components, handling state, and connecting user actions to rendered views. Guided examples grow from a simple interface to a full feature.'
  WHEN 'BOOK-TECH-1010' THEN 'Discover a practical data science workflow: ask a question, prepare a dataset, explore patterns, and communicate findings with statistical thinking and clear examples.'
  WHEN 'BOOK-TECH-1011' THEN 'Develop Java design skills with generics, concurrency, streams, and careful API choices. Focused examples explain the tradeoffs behind robust, readable systems.'
  WHEN 'BOOK-TECH-1012' THEN 'Understand how teams automate builds, tests, deployments, and monitoring. Connect collaboration practices with tools that help software reach users reliably.'
  WHEN 'BOOK-TECH-1013' THEN 'Move beyond basic queries with window functions, query planning, advanced joins, and data modeling. Learn to answer complex questions while keeping performance in view.'
  WHEN 'BOOK-TECH-1014' THEN 'Start with tables and simple queries, then practice filtering, sorting, grouping, and joining data. Step-by-step exercises make relational databases easier to explore.'
  WHEN 'BOOK-TECH-1015' THEN 'Study deeper JavaScript behavior through event loops, async flows, memory, modules, and language edge cases. Practical scenarios help developers make deliberate choices.'
  WHEN 'BOOK-TECH-1016' THEN 'Build a React interface from small components, then add props, state, effects, and navigation. Emphasis on clear data flow supports maintainable applications.'
  WHEN 'BOOK-TECH-1017' THEN 'Tackle React architecture with custom hooks, performance profiling, context boundaries, and resilient UI states. Examples focus on maintainability as applications scale.'
  WHEN 'BOOK-TECH-1018' THEN 'Learn C# fundamentals through types, methods, collections, and object-oriented design. Small exercises reinforce skills for dependable .NET applications.'
  WHEN 'BOOK-TECH-1019' THEN 'Get productive with JavaScript through short lessons on values, functions, the DOM, events, and fetch. Turn each concept into a working browser example.'
  WHEN 'BOOK-TECH-1020' THEN 'Explore machine learning from data preparation to model evaluation. Clear examples introduce supervised learning, feature selection, and how to assess results.'
  WHEN 'BOOK-TECH-1021' THEN 'Deepen Java fluency with object-oriented design, collections, exceptions, streams, and testing. Guided exercises turn core language knowledge into sound application code.'
  WHEN 'BOOK-TECH-1022' THEN 'Learn Python by writing small programs with strings, collections, loops, functions, and files. Gradual exercises build readable coding habits one concept at a time.'
  WHEN 'BOOK-TECH-1023' THEN 'Use modern C# features for expressive applications. Explore async programming, LINQ, generics, and architecture through examples that explain implementation tradeoffs.'
  WHEN 'BOOK-TECH-1024' THEN 'Go deeper into machine learning with model selection, regularization, cross-validation, and error analysis. Compare approaches and communicate uncertainty in real projects.'
  ELSE description
END
WHERE sku BETWEEN 'BOOK-TECH-1000' AND 'BOOK-TECH-1024';

